// Enhanced Custom Hook for Completed Operations Monitoring
const useCompletedOperations = () => {
  const [completedOperations, setCompletedOperations] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [connectionStatus, setConnectionStatus] = useState('connecting');
  const unsubscribeRef = useRef(null);

  const fetchCompletedOperations = useCallback(async () => {
    setLoading(true);
    setError(null);
    setConnectionStatus('connecting');
    
    try {
      const poQuery = query(
        collection(db, 'purchaseOrders'),
        orderBy('updatedAt', 'desc')
      );
      
      const querySnapshot = await getDocs(poQuery);
      const completedOps = [];
      
      querySnapshot.forEach((doc) => {
        try {
          const poData = doc.data();
          const materialTracking = poData.materialTracking || {};
          
          Object.entries(materialTracking).forEach(([operationKey, materialInfo]) => {
            if (materialInfo?.status === 'completed' && materialInfo.completedQuantity > 0) {
              const [itemIndexStr, operation] = operationKey.split('_');
              const itemIndex = parseInt(itemIndexStr);
              const item = poData.items?.[itemIndex];
              
              if (item && item.operation === operation) {
                completedOps.push({
                  id: `${doc.id}_${operationKey}`,
                  poId: doc.id,
                  poNumber: poData.poNumber || 'N/A',
                  vendorId: poData.vendorId || '',
                  vendorName: poData.vendorName || 'Unknown Vendor',
                  vendorLocation: poData.vendorLocation || 'Location not specified',
                  contactPerson: poData.contactPerson || 'Not specified',
                  contactPhone: poData.contactPhone || 'Not specified',
                  itemIndex,
                  operation,
                  itemDescription: item.description || `Item ${itemIndex + 1}`,
                  quantity: Number(item.quantity) || 0,
                  completedQuantity: Number(materialInfo.completedQuantity) || 0,
                  unit: item.unit || 'pcs',
                  unitPrice: Number(item.unitPrice) || 0,
                  specifications: item.specifications || '',
                  material: item.material || '',
                  materialInfo: materialInfo,
                  completedAt: materialInfo.lastUpdated || poData.updatedAt,
                  createdAt: poData.createdAt,
                  totalValue: (Number(item.quantity) || 0) * (Number(item.unitPrice) || 0),
                  completedValue: (Number(materialInfo.completedQuantity) || 0) * (Number(item.unitPrice) || 0)
                });
              }
            }
          });
        } catch (docError) {
          console.error(`Error processing document ${doc.id}:`, docError);
        }
      });
      
      setCompletedOperations(completedOps);
      setConnectionStatus('connected');
    } catch (err) {
      console.error('Failed to fetch completed operations:', err);
      setError(err.message);
      setConnectionStatus('error');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    let mounted = true;

    const setupRealtimeListener = () => {
      try {
        if (unsubscribeRef.current) {
          unsubscribeRef.current();
        }

        const poQuery = query(
          collection(db, 'purchaseOrders'),
          orderBy('updatedAt', 'desc')
        );

        unsubscribeRef.current = onSnapshot(
          poQuery,
          (snapshot) => {
            if (!mounted) return;
            
            setConnectionStatus('connected');
            
            const hasMaterialChanges = snapshot.docChanges().some(change => {
              if (change.type === 'added' || change.type === 'modified') {
                const poData = change.doc.data();
                return poData.materialTracking;
              }
              return false;
            });

            if (hasMaterialChanges) {
              fetchCompletedOperations();
            }
          },
          (error) => {
            if (!mounted) return;
            console.error('Real-time completed operations listener error:', error);
            setConnectionStatus('error');
            setError('Real-time updates disconnected');
          }
        );
      } catch (error) {
        if (!mounted) return;
        console.error('Error setting up real-time listener:', error);
        setConnectionStatus('error');
        setError(error.message);
      }
    };

    setupRealtimeListener();
    
    return () => {
      mounted = false;
      if (unsubscribeRef.current) {
        unsubscribeRef.current();
      }
    };
  }, [fetchCompletedOperations]);

  useEffect(() => {
    fetchCompletedOperations();
  }, [fetchCompletedOperations]);

  const retryConnection = () => {
    setConnectionStatus('connecting');
    setError(null);
    fetchCompletedOperations();
  };

  return {
    completedOperations,
    loading,
    error,
    connectionStatus,
    refetch: fetchCompletedOperations,
    retryConnection
  };
};

// Enhanced Custom Hook for Task Management
const useTaskManager = () => {
  const [tasks, setTasks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [connectionStatus, setConnectionStatus] = useState('connecting');
  const unsubscribeRef = useRef(null);

  const fetchTasks = useCallback(async () => {
    setLoading(true);
    setError(null);
    setConnectionStatus('connecting');
    
    try {
      // Try ordered query first; if index is missing, fall back to unordered and sort client-side
      let ordered = true;
      let tasksQuery = query(
        collection(db, 'industrialTasks'),
        where('autoGeneratedFrom', '==', 'status_manager'),
        orderBy('createdAt', 'desc')
      );
      
      let querySnapshot;
      try {
        querySnapshot = await getDocs(tasksQuery);
      } catch (err) {
        if (err?.code === 'failed-precondition') {
          // Missing composite index; fall back without orderBy
          ordered = false;
          tasksQuery = query(
            collection(db, 'industrialTasks'),
            where('autoGeneratedFrom', '==', 'status_manager')
          );
          querySnapshot = await getDocs(tasksQuery);
        } else {
          throw err;
        }
      }
      const tasksList = [];
      
      querySnapshot.forEach((doc) => {
        try {
          tasksList.push({
            id: doc.id,
            ...doc.data()
          });
        } catch (docError) {
          console.error(`Error processing task document ${doc.id}:`, docError);
        }
      });
      // If we fell back to unordered, sort client-side by createdAt desc
      if (!ordered) {
        tasksList.sort((a, b) => {
          const aTime = a?.createdAt?.seconds || a?.createdAt?._seconds || 0;
          const bTime = b?.createdAt?.seconds || b?.createdAt?._seconds || 0;
          return bTime - aTime;
        });
      }
      setTasks(tasksList);
      setConnectionStatus('connected');
    } catch (err) {
      console.error('Failed to fetch tasks:', err);
      setError(err.message);
      setConnectionStatus('error');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    let mounted = true;

    const setupRealtimeListener = () => {
      try {
        if (unsubscribeRef.current) {
          unsubscribeRef.current();
        }
        
        const attachListener = (ordered = true) => {
          const baseQuery = ordered
            ? query(
                collection(db, 'industrialTasks'),
                where('autoGeneratedFrom', '==', 'status_manager'),
                orderBy('createdAt', 'desc')
              )
            : query(
                collection(db, 'industrialTasks'),
                where('autoGeneratedFrom', '==', 'status_manager')
              );

          unsubscribeRef.current = onSnapshot(
            baseQuery,
            (snapshot) => {
              if (!mounted) return;
              
              const tasksList = [];
              snapshot.forEach((doc) => {
                try {
                  tasksList.push({
                    id: doc.id,
                    ...doc.data()
                  });
                } catch (docError) {
                  console.error(`Error processing task document ${doc.id}:`, docError);
                }
              });
              // If we fell back to unordered, sort client-side by createdAt desc
              if (!ordered) {
                tasksList.sort((a, b) => {
                  const aTime = a?.createdAt?.seconds || a?.createdAt?._seconds || 0;
                  const bTime = b?.createdAt?.seconds || b?.createdAt?._seconds || 0;
                  return bTime - aTime;
                });
              }
              setTasks(tasksList);
              setConnectionStatus('connected');
            },
            (error) => {
              if (!mounted) return;
              if (ordered && error?.code === 'failed-precondition') {
                // Missing composite index; retry without orderBy
                console.warn('Missing composite index for ordered real-time query. Falling back without orderBy.');
                if (unsubscribeRef.current) unsubscribeRef.current();
                attachListener(false);
                return;
              }
              console.error('Real-time tasks listener error:', error);
              setConnectionStatus('error');
              setError('Real-time updates disconnected');
            }
          );
        };

        attachListener(true);
      } catch (error) {
        if (!mounted) return;
        console.error('Error setting up tasks listener:', error);
        setConnectionStatus('error');
        setError(error.message);
      }
    };

    setupRealtimeListener();
    
    return () => {
      mounted = false;
      if (unsubscribeRef.current) {
        unsubscribeRef.current();
      }
    };
  }, []);

  useEffect(() => {
    fetchTasks();
  }, [fetchTasks]);

  const updateTaskStatus = async (taskId, newStatus, currentUser) => {
    try {
      if (!taskId) {
        throw new Error('Task ID is required');
      }

      const taskRef = doc(db, 'industrialTasks', taskId);
      const updateData = {
        status: newStatus,
        updatedAt: serverTimestamp(),
        lastUpdatedBy: {
          uid: currentUser?.uid,
          name: currentUser?.displayName,
          email: currentUser?.email,
          timestamp: serverTimestamp()
        }
      };

      // Handle status-specific updates
      if (newStatus === 'completed') {
        updateData.completed = true;
        updateData.progress = 100;
        updateData.completedAt = serverTimestamp();
      } else if (newStatus === 'in_progress') {
        updateData.progress = 50;
        updateData.startedAt = updateData.startedAt || serverTimestamp();
      }

      await updateDoc(taskRef, updateData);
      return { success: true };
    } catch (error) {
      console.error('Error updating task status:', error);
      throw new Error(`Failed to update task status: ${error.message}`);
    }
  };

  const updateTaskProgress = async (taskId, progress, currentUser) => {
    try {
      if (!taskId) {
        throw new Error('Task ID is required');
      }

      const taskRef = doc(db, 'industrialTasks', taskId);
      const normalizedProgress = Math.min(100, Math.max(0, Number(progress) || 0));
      
      await updateDoc(taskRef, {
        progress: normalizedProgress,
        updatedAt: serverTimestamp(),
        lastUpdatedBy: {
          uid: currentUser?.uid,
          name: currentUser?.displayName,
          email: currentUser?.email,
          timestamp: serverTimestamp()
        }
      });
      
      return { success: true };
    } catch (error) {
      console.error('Error updating task progress:', error);
      throw new Error(`Failed to update task progress: ${error.message}`);
    }
  };

  return {
    tasks,
    loading,
    error,
    connectionStatus,
    refetch: fetchTasks,
    updateTaskStatus,
    updateTaskProgress
  };
};

