// Main Enhanced DailyToDoList Component
export default function DailyToDoList() {
  const { showSuccess, showError, showInfo } = useNotification();
  const { currentUser } = useAuth();
  
  // Custom hooks for data management
  const {
    completedOperations,
    loading: operationsLoading,
    error: operationsError,
    connectionStatus: operationsConnectionStatus,
    refetch: refetchOperations,
    retryConnection: retryOperationsConnection
  } = useCompletedOperations();

  const {
    tasks,
    loading: tasksLoading,
    error: tasksError,
    connectionStatus: tasksConnectionStatus,
    refetch: refetchTasks,
    updateTaskStatus,
    updateTaskProgress
  } = useTaskManager();

  // Local state
  const [activeTab, setActiveTab] = useState('all');
  const [generatingTasks, setGeneratingTasks] = useState(false);
  const [generatedTasks, setGeneratedTasks] = useState([]);
  const [updatingTasks, setUpdatingTasks] = useState({});
  
  // Table state
  const [filters, setFilters] = useState({
    status: 'all',
    priority: 'all',
    search: ''
  });
  
  const [sortConfig, setSortConfig] = useState({ key: 'createdAt', direction: 'desc' });
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(20);

  // Filter and sort tasks
  const filteredTasks = useMemo(() => {
    let filtered = [...tasks];

    // Apply tab filter
    if (activeTab === 'active') {
      filtered = filtered.filter(task => !task.completed && task.status !== 'completed');
    } else if (activeTab === 'completed') {
      filtered = filtered.filter(task => task.completed || task.status === 'completed');
    }

    // Apply status filter
    if (filters.status !== 'all') {
      filtered = filtered.filter(task => task.status === filters.status);
    }

    // Apply priority filter
    if (filters.priority !== 'all') {
      filtered = filtered.filter(task => task.priority === filters.priority);
    }

    // Apply search filter
    if (filters.search.trim()) {
      const query = filters.search.toLowerCase();
      filtered = filtered.filter(task => 
        task.title?.toLowerCase().includes(query) ||
        task.description?.toLowerCase().includes(query) ||
        task.sourcePO?.toLowerCase().includes(query) ||
        task.sourceItemDescription?.toLowerCase().includes(query) ||
        task.sourceVendorName?.toLowerCase().includes(query)
      );
    }

    // Apply sorting
    filtered.sort((a, b) => {
      const dir = sortConfig.direction === 'asc' ? 1 : -1;
      
      switch (sortConfig.key) {
        case 'createdAt':
          const aCreated = a.createdAt?.toDate?.() ? a.createdAt.toDate() : (a.createdAt ? new Date(a.createdAt) : new Date(0));
          const bCreated = b.createdAt?.toDate?.() ? b.createdAt.toDate() : (b.createdAt ? new Date(b.createdAt) : new Date(0));
          return (aCreated - bCreated) * dir;
          
        case 'dueDate':
          const aDue = a.dueDate?.toDate?.() ? a.dueDate.toDate() : (a.dueDate ? new Date(a.dueDate) : new Date(0));
          const bDue = b.dueDate?.toDate?.() ? b.dueDate.toDate() : (b.dueDate ? new Date(b.dueDate) : new Date(0));
          return (aDue - bDue) * dir;
          
        case 'priority':
          const priorityOrder = { urgent: 4, high: 3, medium: 2, low: 1 };
          return (priorityOrder[a.priority] - priorityOrder[b.priority]) * dir;
          
        case 'progress':
          return (a.progress - b.progress) * dir;
          
        case 'title':
          return (a.title || '').localeCompare(b.title || '') * dir;
          
        case 'sourcePO':
          return (a.sourcePO || '').localeCompare(b.sourcePO || '') * dir;
          
        default:
          return 0;
      }
    });

    return filtered;
  }, [tasks, activeTab, filters, sortConfig]);

  // Filter and sort operations
  const filteredOperations = useMemo(() => {
    let filtered = [...completedOperations];

    // Apply sorting
    filtered.sort((a, b) => {
      const dir = sortConfig.direction === 'asc' ? 1 : -1;
      
      switch (sortConfig.key) {
        case 'poNumber':
          return (a.poNumber || '').localeCompare(b.poNumber || '') * dir;
          
        case 'operation':
          return (a.operation || '').localeCompare(b.operation || '') * dir;
          
        case 'vendorName':
          return (a.vendorName || '').localeCompare(b.vendorName || '') * dir;
          
        case 'completedQuantity':
          return (a.completedQuantity - b.completedQuantity) * dir;
          
        case 'completedValue':
          return (a.completedValue - b.completedValue) * dir;
          
        case 'completedAt':
          const aCompleted = a.completedAt?.toDate?.() ? a.completedAt.toDate() : (a.completedAt ? new Date(a.completedAt) : new Date(0));
          const bCompleted = b.completedAt?.toDate?.() ? b.completedAt.toDate() : (b.completedAt ? new Date(b.completedAt) : new Date(0));
          return (aCompleted - bCompleted) * dir;
          
        default:
          return 0;
      }
    });

    return filtered;
  }, [completedOperations, sortConfig]);

  // Calculate statistics
  const stats = useMemo(() => {
    const activeTasks = tasks.filter(t => !t.completed && t.status !== 'completed');
    const completedTasks = tasks.filter(t => t.completed || t.status === 'completed');
    const urgentTasks = tasks.filter(t => t.priority === 'urgent' && !t.completed);
    
    return {
      totalTasks: tasks.length,
      activeTasks: activeTasks.length,
      completedTasks: completedTasks.length,
      readyForCollection: completedOperations.length,
      urgentTasks: urgentTasks.length
    };
  }, [tasks, completedOperations]);

  // Pagination
  const totalPages = Math.ceil(
    (activeTab === 'operations' ? filteredOperations.length : filteredTasks.length) / itemsPerPage
  );

  // Reset to page 1 when filters change
  useEffect(() => {
    setCurrentPage(1);
  }, [filters, activeTab, sortConfig]);

  // Handlers
  const handleSort = (key) => {
    setSortConfig(prev => ({
      key,
      direction: prev.key === key && prev.direction === 'desc' ? 'asc' : 'desc'
    }));
  };

  const handleGenerateTasks = async (selectedOperations) => {
    if (!selectedOperations.length) return;
    
    setGeneratingTasks(true);
    try {
      const results = await checkAndCreateMaterialTasks(selectedOperations, currentUser);
      
      const successfulTasks = results.filter(result => result.result.success);
      const failedTasks = results.filter(result => !result.result.success);
      
      if (successfulTasks.length > 0) {
        setGeneratedTasks(successfulTasks.map(t => t.operation));
        showSuccess(`Successfully created ${successfulTasks.length} material collection tasks`);
        await refetchTasks();
        setActiveTab('all');
      }
      
      if (failedTasks.length > 0) {
        showError(`Failed to create ${failedTasks.length} tasks. They may already exist.`);
      }
      
    } catch (error) {
      console.error('Error generating tasks:', error);
      showError('Failed to generate tasks: ' + error.message);
    } finally {
      setGeneratingTasks(false);
    }
  };

  const handleTaskStatusUpdate = async (taskId, newStatus) => {
    const updateKey = `status-${taskId}`;
    
    try {
      setUpdatingTasks(prev => ({ ...prev, [updateKey]: true }));
      await updateTaskStatus(taskId, newStatus, currentUser);
      showSuccess(`Task status updated to ${TASK_STATUS[newStatus]?.label || newStatus}`);
    } catch (error) {
      console.error('Error updating task status:', error);
      showError('Failed to update task status: ' + error.message);
    } finally {
      setUpdatingTasks(prev => {
        const copy = { ...prev };
        delete copy[updateKey];
        return copy;
      });
    }
  };

  const handleTaskProgressUpdate = async (taskId, progress) => {
    const updateKey = `progress-${taskId}`;
    
    try {
      setUpdatingTasks(prev => ({ ...prev, [updateKey]: true }));
      await updateTaskProgress(taskId, progress, currentUser);
    } catch (error) {
      console.error('Error updating task progress:', error);
      showError('Failed to update task progress: ' + error.message);
    } finally {
      setUpdatingTasks(prev => {
        const copy = { ...prev };
        delete copy[updateKey];
        return copy;
      });
    }
  };

  const handleCollectionStatusUpdate = async (taskId, newStatus, collectionDetails) => {
    const updateKey = `collection-${taskId}`;
    
    try {
      setUpdatingTasks(prev => ({ ...prev, [updateKey]: true }));
      await updateCollectionStatus(taskId, newStatus, collectionDetails, currentUser);
      showSuccess(`Collection status updated to ${COLLECTION_STATUS[newStatus]?.label || newStatus}`);
      await refetchTasks();
    } catch (error) {
      console.error('Error updating collection status:', error);
      showError('Failed to update collection status: ' + error.message);
    } finally {
      setUpdatingTasks(prev => {
        const copy = { ...prev };
        delete copy[updateKey];
        return copy;
      });
    }
  };

  const handleVerificationUpdate = async (taskId, verificationUpdates) => {
    const updateKey = `verification-${taskId}`;
    
    try {
      setUpdatingTasks(prev => ({ ...prev, [updateKey]: true }));
      await updateCollectionVerification(taskId, verificationUpdates, currentUser);
      showSuccess('Verification status updated');
      await refetchTasks();
    } catch (error) {
      console.error('Error updating verification:', error);
      showError('Failed to update verification status: ' + error.message);
    } finally {
      setUpdatingTasks(prev => {
        const copy = { ...prev };
        delete copy[updateKey];
        return copy;
      });
    }
  };

  const handleRefreshAll = async () => {
    try {
      await Promise.all([refetchOperations(), refetchTasks()]);
      showSuccess('Data refreshed successfully');
    } catch (error) {
      showError('Failed to refresh data');
    }
  };

  // Loading state
  if (operationsLoading && tasksLoading && completedOperations.length === 0 && tasks.length === 0) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-gray-50 to-gray-100">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-indigo-600 mx-auto"></div>
          <p className="mt-4 text-gray-600 text-lg">Loading Daily To-Do List...</p>
          <p className="text-sm text-gray-500 mt-2">Preparing your material collection tasks</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 p-4 lg:p-6">
      {/* Header */}
      <div className="bg-white rounded-2xl shadow-xl border border-gray-200 overflow-hidden mb-6 lg:mb-8">
        <div className="relative bg-gradient-to-r from-indigo-600 to-purple-600 p-6 lg:p-8">
          <div className="flex items-center justify-between flex-wrap gap-4">
            <div>
              <h1 className="text-2xl lg:text-3xl font-bold text-white">Daily To-Do List</h1>
              <p className="text-indigo-100 text-sm lg:text-base mt-2">
                Material collection tasks from completed operations • {filteredTasks.length} tasks in {activeTab} tab
              </p>
            </div>
            <div className="flex items-center space-x-3 flex-wrap gap-2">
              <ConnectionStatusIndicator 
                status={operationsConnectionStatus === 'connected' && tasksConnectionStatus === 'connected' ? 'connected' : 
                       operationsConnectionStatus === 'error' || tasksConnectionStatus === 'error' ? 'error' : 'connecting'}
                onRetry={() => {
                  retryOperationsConnection();
                  refetchTasks();
                }}
                loading={operationsLoading || tasksLoading}
              />
              <button
                onClick={handleRefreshAll}
                disabled={operationsLoading || tasksLoading}
                className="inline-flex items-center px-4 py-2 bg-white/20 hover:bg-white/30 text-white rounded-xl transition-all duration-200 backdrop-blur-sm disabled:opacity-50 font-medium shadow-sm"
              >
                <FiRefreshCw className={`mr-2 ${operationsLoading || tasksLoading ? 'animate-spin' : ''}`} size={16} />
                Refresh
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Stats Overview */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-6 lg:mb-8">
        <StatsCard
          title="All Tasks"
          value={stats.totalTasks}
          subtitle="total tasks"
          icon={FiList}
          color="gray"
        />
        <StatsCard
          title="Active Tasks"
          value={stats.activeTasks}
          subtitle="in progress"
          icon={FiActivity}
          color="blue"
        />
        <StatsCard
          title="Completed Tasks"
          value={stats.completedTasks}
          subtitle="finished"
          icon={FiCheckCircle}
          color="green"
        />
        <StatsCard
          title="Ready for Collection"
          value={stats.readyForCollection}
          subtitle="operations"
          icon={FiPackage}
          color="purple"
        />
      </div>

      {/* Navigation Tabs */}
      <div className="bg-white rounded-2xl shadow-lg border border-gray-200 p-2 mb-6 lg:mb-8">
        <nav className="flex space-x-1 flex-wrap gap-2">
          {[
            { key: 'all', label: 'All Tasks', count: stats.totalTasks, icon: FiList },
            { key: 'active', label: 'Active Tasks', count: stats.activeTasks, icon: FiActivity },
            { key: 'completed', label: 'Completed Tasks', count: stats.completedTasks, icon: FiCheckCircle },
            { key: 'operations', label: 'Completed Operations', count: stats.readyForCollection, icon: FiPackage },
          ].map((tab) => {
            const Icon = tab.icon;
            return (
              <button
                key={tab.key}
                onClick={() => setActiveTab(tab.key)}
                className={`
                  flex items-center flex-1 min-w-[140px] py-3 px-4 rounded-xl text-sm font-medium 
                  transition-all duration-200 transform hover:scale-[1.02]
                  ${activeTab === tab.key 
                    ? 'bg-indigo-600 text-white shadow-lg' 
                    : 'text-gray-700 hover:bg-gray-50'
                  }
                `}
              >
                <Icon className="mr-2 flex-shrink-0" size={16} />
                <span className="truncate">{tab.label}</span>
                <span className={`
                  ml-2 text-xs px-2 py-1 rounded-full min-w-[24px] text-center flex-shrink-0
                  ${activeTab === tab.key ? 'bg-white/20' : 'bg-gray-100 text-gray-600'}
                `}>
                  {tab.count}
                </span>
              </button>
            );
          })}
        </nav>
      </div>

      {/* Table Controls */}
      {(activeTab === 'all' || activeTab === 'active' || activeTab === 'completed') && (
        <div className="bg-white rounded-2xl shadow-lg border border-gray-200 p-6 mb-6 lg:mb-8">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {/* Search */}
            <div className="lg:col-span-2">
              <label className="block text-sm font-medium text-gray-700 mb-2">Search Tasks</label>
              <div className="relative">
                <FiSearch className="absolute left-3 top-3 text-gray-400" size={16} />
                <input
                  type="text"
                  placeholder="Search tasks, PO numbers, vendors, or items..."
                  value={filters.search}
                  onChange={(e) => setFilters(prev => ({ ...prev, search: e.target.value }))}
                  className="w-full pl-10 pr-4 py-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all duration-200"
                />
              </div>
            </div>

            {/* Status Filter */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Status</label>
              <select
                value={filters.status}
                onChange={(e) => setFilters(prev => ({ ...prev, status: e.target.value }))}
                className="w-full px-3 py-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all duration-200"
              >
                <option value="all">All Status</option>
                {Object.entries(TASK_STATUS).map(([value, { label }]) => (
                  <option key={value} value={value}>{label}</option>
                ))}
              </select>
            </div>

            {/* Items Per Page */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Items Per Page</label>
              <select
                value={itemsPerPage}
                onChange={(e) => setItemsPerPage(Number(e.target.value))}
                className="w-full px-3 py-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all duration-200"
              >
                <option value={10}>10 items</option>
                <option value={20}>20 items</option>
                <option value={50}>50 items</option>
                <option value={100}>100 items</option>
              </select>
            </div>
          </div>

          <div className="flex justify-between items-center mt-4 pt-4 border-t border-gray-200">
            <button
              onClick={() => {
                setFilters({
                  status: 'all',
                  priority: 'all',
                  search: ''
                });
                setSortConfig({ key: 'createdAt', direction: 'desc' });
              }}
              className="text-indigo-600 hover:text-indigo-800 font-medium transition-colors text-sm"
            >
              Clear All Filters
            </button>
            
            <div className="text-sm text-gray-600">
              Showing {Math.min(filteredTasks.length, itemsPerPage)} of {filteredTasks.length} tasks
            </div>
          </div>
        </div>
      )}

      {/* Main Content */}
      <main className="mb-6 lg:mb-8">
        {/* Task Tables */}
        {(activeTab === 'all' || activeTab === 'active' || activeTab === 'completed') && (
          <div className="space-y-4">
            <TaskTable
              tasks={filteredTasks}
              onStatusUpdate={handleTaskStatusUpdate}
              onProgressUpdate={handleTaskProgressUpdate}
              onCollectionUpdate={handleCollectionStatusUpdate}
              onVerificationUpdate={handleVerificationUpdate}
              updatingTasks={updatingTasks}
              sortConfig={sortConfig}
              onSort={handleSort}
              currentPage={currentPage}
              itemsPerPage={itemsPerPage}
            />
            
            {filteredTasks.length > 0 && (
              <Pagination
                currentPage={currentPage}
                totalPages={totalPages}
                onPageChange={setCurrentPage}
                totalItems={filteredTasks.length}
                itemsPerPage={itemsPerPage}
              />
            )}
          </div>
        )}

        {/* Operations Table */}
        {activeTab === 'operations' && (
          <div className="space-y-4">
            <CompletedOperationsTable
              completedOperations={filteredOperations}
              onGenerateTasks={handleGenerateTasks}
              generatingTasks={generatingTasks}
              generatedTasks={generatedTasks}
              sortConfig={sortConfig}
              onSort={handleSort}
              currentPage={currentPage}
              itemsPerPage={itemsPerPage}
            />
            
            {filteredOperations.length > 0 && (
              <Pagination
                currentPage={currentPage}
                totalPages={totalPages}
                onPageChange={setCurrentPage}
                totalItems={filteredOperations.length}
                itemsPerPage={itemsPerPage}
              />
            )}
          </div>
        )}
      </main>

      {/* Error Display */}
      {(operationsError || tasksError) && (
        <div className="fixed bottom-4 right-4 bg-red-50 border border-red-200 rounded-xl p-4 shadow-lg max-w-md z-50">
          <div className="flex items-start space-x-3">
            <FiAlertCircle className="text-red-600 mt-0.5 flex-shrink-0" size={20} />
            <div className="flex-1 min-w-0">
              <p className="text-red-800 font-semibold">Connection Error</p>
              <p className="text-red-700 text-sm mt-1">
                {operationsError || tasksError}
              </p>
              <button
                onClick={handleRefreshAll}
                className="text-red-600 hover:text-red-800 text-sm font-medium mt-2"
              >
                Try to reconnect
              </button>
            </div>
            <button
              onClick={() => {
                // Clear errors
                if (operationsError) refetchOperations();
                if (tasksError) refetchTasks();
              }}
              className="text-red-400 hover:text-red-600 transition-colors"
            >
              <FiX size={16} />
            </button>
          </div>
        </div>
      )}
    </div>
  );
}